#include <thread>

using namespace std;

struct DataItem {
    string customer_id;
    int order_id;
    datetime order_time;
    string product_id;
    string category;
    double price;
};

class DataAnalyzer {
public:
    DataAnalyzer(const char* csv_dir, const char* json_dir, const char* db_url) :
        csv_dir_(csv_dir), json_dir_(json_dir), db_url_(db_url) {}

    vector<vector<string>> readData() {
        vector<vector<string>> data;
        string dir = csv_dir_;
        for (string file : listFiles(dir)) {
            if (!file.empty() && file.find('.') != string::npos) {
                stringstream ss;
                file_name = file.c_str();
                ss << file_name;
                vector<string> current;
                string delimiter = ",";
                size_t start = 0, end;
                while ((end = ss.find(delimiter)) != string::npos) {
                    string token = ss.substr(start, end - start);
                    current.push_back(token);
                    start = end + delimiter.length();
                }
                data.push_back(current);
            }
        }

        dir = json_dir_;
        for (string file : listFiles(dir)) {
            stringstream ss;
            file_name = file.c_str();
            ss << "[[" << file_name << "]]";
            vector<string> current = json.loads(ss.str());
            data.push_back(current);
        }

        return data;
    }

private:
    vector<string> listFiles(const char* dir) {
        vector<string> files;
        string path, name;
        if ((path = opendir(dir)) != string::npos) {
            while ((name = readdir(path)) != string::npos) {
                files.push_back(name);
                closepath(path);
                path = nextdir(path);
            }
        }
        return files;
    }

    void cleanData(vector<vector<string>>& data) {
        // 去重：将重复的记录合并，取平均值
        map<int, vector<string>> unique_map;
        for (const auto& item : data) {
            tuple<string, string, datetime, string, string, double> key(item[0], item[1], item[2],
                                                                item[3], item[4], stod(item[5]));
            unique_map[key] = {item};
        }

        vector<vector<string>> cleaned_data;
        for (const auto& [key, group] : unique_map) {
            if (group.size() > 1) {
                // 计算平均价格
                double avg_price = accumulate(group.begin(), group.end(), 0.0) / static_cast<double>(group.size());
                cleaned_data.push_back({key.get<0>(), key.get<1>(), key.get<2>, 
                                        key.get<3>(), to_string(avg_price), avg_price});
            } else {
                // 留下第一个记录
                cleaned_data.push_back(get<all_touples>(key));
            }
        }

        data = move(cleaned_data);
    }

    bool handleMissingValues(vector<vector<string>>& data) {
        for (auto& item : data) {
            if (!item.empty()) {
                // 替换缺失值：取第一个非缺失的值
                for (size_t i = 0; i < item.size(); ++i) {
                    if (!isna(item[i].c_str())) {
                        item[i] = string(item[i].c_str());
                        break;
                    }
                }
            }
        }
        return true;
    }

    void standardizeText(vector<vector<string>>& data) {
        // 去除特殊符号，分词
        for (auto& item : data) {
            if (!item.empty()) {
                string text = item[4];
                // 去掉非字母、数字和空格的字符
                text = regex_replace(text, "[^a-zA-Z0-9\\s]", "");
                vector<string> words = tokenized(text);
                item[4] = join(words, " ");
            }
        }
    }

private:
    vector<string> tokenize(const string& text) {
        vector<string> tokens;
        istringstream iss(text);
        string word;
        while (iss >> word) {
            tokens.push_back(word);
        }
        return tokens;
    }

    void saveData(vector<vector<string>>& data) {
        // 将数据保存为 CSV 文件
        ofstream csv_file("cleaned_data.csv", ios::out | ios::binary);
        if (!csv_file.is_open()) {
            perror(csv_file);
            return;
        }
        vector<vector<double>> numeric_data;
        for (const auto& item : data) {
            vector<double> row;
            try {
                // 转换为数值类型
                row.push_back(stod(item[0]));
                row.push_back(stod(item[1]));
                row.push_back(item[2].time());
                row.push_back(stod(item[3]));
                row.push_back(stod(item[4]));
                row.push_back(item[5]);
                numeric_data.push_back(row);
            } catch (const invalid_argument& ia) {
                perror(ia);
                return;
            }
        }

        csv_file << "cleaned_data.csv";
        csv_file << numeric_data;
        csv_file.close();
    }

    bool insertData(const vector<vector<string>>& data) {
        // 插入到 MySQL 数据库
        try {
            MySQL *mysql = Meyou("localhost", 3306, "company", "user", "password", 0, sizeof(data[0][5]));
            if (!mysql) {
                perror(mysql);
                return false;
            }

            vector<double> x(6), y(6);
            for (size_t i = 0; i < data.size(); ++i) {
                memcpy(&x, data[i].c_str(), sizeof(data[0][0]) * 6);
                mysql->execute("INSERT INTO cleaned_data (cleaned_entry) VALUES (%s)", x);
            }

            return true;
        } catch (const exception& e) {
            cerr << "插入数据错误：" << e.what() << endl;
            return false;
        }
    }
};

int main() {
    DataAnalyzer analyzer("data_csv", "data_json", "localhost");

    vector<vector<string>> data;
    thread_group threads;
    for (const auto& file : listFiles("data_csv")) {
        string file_name = file.c_str();
        threads.push_back(thread(target=analyzer.readData, args=(file_name,)));
    }
    for (thread_t thread : threads) {
        thread.join();
        data.insert(data.end(), thread.get().second.begin(), thread.get().second.end());
    }

    analyzer.cleanData(data);
    bool handle_missing = analyzer.handleMissingValues(data);
    if (!handle_missing) {
        return;
    }

    analyzer.standardizeText(data);

    analyzer.saveData(data);

    return 0;
}
```

