###Written/Analyzed Code (Including Comments)

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <time.h>
#include <sys/time_t>
#include <numeric>

using namespace std;

struct DateTime {
    int year, month, day, hour, minute;
};

struct Product {
    string name;
    string description;
    double price;
};

struct Chat {
    string customer_id;
    string message;
};

struct Order {
    string customer_id;
    string order_date;
    double sales;
    int quantity;
    Product product;
};

class DataPreprocessor {
private:
    vector<vector<double>> data;

public:
    DataPreprocessor() {}

    void loadCSV(const string& filename) {
        ifstream file(filename);
        if (!file) {
            cout << "Error: Could not open file" << endl;
            return;
        }

        string line;
        while (getline(file, line)) {
            vector<double> row;
            istringstream iss(line);
            string token;

            while (iss >> token) {
                if (isalpha(token[0])) {
                    switch(token[0]) {
                        case 'd': // 数字
                            row.push_back(stod(token));
                            break;
                        default: 
                            cout << "Error: Invalid data format" << endl;
                            return;
                    }
                } else {
                    row.push_back(stoull(token));
                }
            }

            data.push_back(row);
        }
    }

    vector<vector<double>> getCleanedData() {
        vector<vector<double>> cleaned_data;
        for (const auto& sample : data) {
            double avg = accumulate(sample.begin(), sample.end(), 0.0) / sample.size();
            double std_dev = sqrt(mean(iota(0, sample.size()), [&](int i) { return (sample[i] - avg) * (sample[i] - avg); }) - pow(avg, 2));

            if (std_dev < 1e-6) {
                cleaned_data.push_back(sample);
                continue;
            }

            double normalized = (sample[0] - min_element(sample.begin(), sample.end())) / 
                               (max_element(sample.begin(), sample.end()) - min_element(sample.begin(), sample.end()));
            cleaned_data.push_back({normalized});
        }

        return cleaned_data;
    }
};

