    DataPreprocessor pre;

    // Example: Load CSV data
    vector<vector<double>> data = pre.loadCSV("sample_data.csv");

    cout << "Data loaded successfully." << endl;

    // Process data
    int num_workers = 4; // Number of worker threads

    for (int i = 0; i < num_workers; ++i) {
        for (const auto& sample : data) {
            double avg = accumulate(sample.begin(), sample.end(), 0.0) / sample.size();
            cout << "Processed average: " << fixed << setprecision(6) << avg << endl;
        }
    }

