#include <sys/time_t>
#include <numeric>

using namespace std;

struct DateTime {
    int year, month, day, hour, minute;
};

struct Product {
    string name;
    string description;
    double price;
};

struct Chat {
    string customer_id;
    string message;
};

struct Order {
    string customer_id;
    string order_date;
    double sales;
    int quantity;
    Product product;
};

class DataPreprocessor {
private:
    vector<vector<double>> data;

public:
    DataPreprocessor() {}

    // Load CSV file and convert it into a vector of vectors
    void loadCSV(const string& filename) {
        ifstream file(filename);
        if (!file.is_open()) {
            cout << "Error: Could not open file" << endl;
            return;
        }

        string line;
        while (getline(file, line)) {
            vector<double> row;
            istringstream iss(line);
            string token;

            // Split the line by whitespace and convert each token to double
            while (iss >> token) {
                if (isalpha(token[0])) {
                    switch (token[0]) {
                        case 'd': // Numeric value
                            try {
                                row.push_back(stod(token));
                            } catch (const exception& e) {
                                cout << "Error: Invalid conversion for token '" << token << "'" << endl;
                                return;
                            }
                            break;
                        default:
                            cout << "Error: Invalid data format in CSV" << endl;
                            return;
                    }
                } else {
                    try {
                        row.push_back(stoull(token));
                    } catch (const exception& e) {
                        cout << "Error: Conversion failed for token '" << token << "'" << endl;
                        return;
                    }
                }
            }

            data.push_back(row);
        }
    }

    // Clean and preprocess the data
    vector<vector<double>> getCleanedData() {
        vector<vector<double>> cleaned_data;

        for (const auto& sample : data) {
            if (sample.empty()) {
                continue;
            }

            // Calculate average and standard deviation of the sample
            double avg = accumulate(sample.begin(), sample.end(), 0.0) / sample.size();
            double mean = avg;
            double variance = numeric_limits<double>::quiet Infinity();

            for (double value : sample) {
                variance = variance == numeric_limits<double>::quiet Infinity() ? 
                    pow(value - mean, 2) :
                        variance + pow(value - mean, 2);
            }
            double std_dev = sqrt(variance / sample.size());

            if (std_dev < 1e-6) {
                cleaned_data.push_back(sample);
                continue;
            }

            // Normalize the data to [0, 1]
            double min_val = *min_element(sample.begin(), sample.end());
            double max_val = *max_element(sample.begin(), sample.end());
            if (max_val - min_val == 0) {
                cleaned_data.push_back({0.0});
                continue;
            }

            double normalized = static_cast<double>(sample[0] - min_val) / 
                               (max_val - min_val);
            cleaned_data.push_back({normalized});
        }

        return cleaned_data;
    }
};
```

